<?php $pageTitle=page_title('Pickup slots'); $page='farmer-slots'; ?>
<div class="dashboard-head reveal"><div><span class="eyebrow">Fulfillment schedule</span><h1>Pickup slots</h1><p>Set recurring availability and see how each upcoming window is filling.</p></div></div>
<div class="detail-grid"><div class="content-card card"><div class="content-head"><div><h2>Recurring schedule</h2><p>Future open slots are generated from these local times.</p></div></div><form method="post" action="<?= e(url('farmer-slots-save')) ?>"><?= csrf_field() ?><div class="form-group"><label>Operating days</label><div class="choice-grid"><?php foreach([1=>'Mon',2=>'Tue',3=>'Wed',4=>'Thu',5=>'Fri',6=>'Sat',0=>'Sun'] as $day=>$label): ?><label class="choice"><input type="checkbox" name="operating_days[]" value="<?= $day ?>" <?= in_array($day,$operatingDays,true)?'checked':'' ?>><span><?= e($label) ?></span></label><?php endforeach; ?></div></div><div class="form-grid three"><div class="form-group"><label for="slots_start">Pickup starts</label><input id="slots_start" name="pickup_start" type="time" value="<?= e($farmerProfile['pickup_start']) ?>" required></div><div class="form-group"><label for="slots_end">Pickup ends</label><input id="slots_end" name="pickup_end" type="time" value="<?= e($farmerProfile['pickup_end']) ?>" required></div><div class="form-group"><label for="slots_cutoff">Order cutoff</label><input id="slots_cutoff" name="cutoff_time" type="time" value="<?= e($farmerProfile['cutoff_time']) ?>" required></div></div><button class="btn" type="submit"><?= icon('calendar') ?> Update schedule</button></form></div><aside class="card card-pad" style="background:linear-gradient(145deg,var(--green-100),white)"><span class="eyebrow">How cutoff works</span><h2 style="margin:0 0 9px;color:var(--green-950);font-size:1.45rem">Clear deadlines build trust.</h2><p class="text-muted">The cutoff is the day before each pickup date. Customers can cancel while their order status is placed or accepted and the cutoff has not passed.</p><div class="alert alert-info mt-3"><?= icon('info') ?><span>Existing orders keep the cutoff that was shown when they were placed.</span></div></aside></div>
<div class="content-card card mt-3"><div class="content-head"><div><h2>Upcoming slot capacity</h2><p>Capacity is reserved when a pickup order is created.</p></div><span class="pill pill-lime"><?= count($pickupSlots) ?> dates</span></div><?php if($pickupSlots): ?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Time</th><th>Market</th><th>Orders</th><th>Capacity</th><th>Status</th></tr></thead><tbody><?php foreach($pickupSlots as $slot): ?><tr><td><strong><?= format_date($slot['pickup_date'],'D, M j, Y') ?></strong></td><td><?= e(date('g:i A',strtotime($slot['start_time']))) ?> – <?= e(date('g:i A',strtotime($slot['end_time']))) ?></td><td><?= e($slot['market_name']) ?><br><small class="text-muted"><?= e($slot['market_address']) ?></small></td><td><?= (int)$slot['actual_orders'] ?></td><td><?= (int)$slot['booked_count'] ?> / <?= (int)$slot['capacity'] ?></td><td><?= status_pill($slot['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><span class="empty-state-icon">📅</span><h3>No future slots yet</h3><p>Choose operating days and save the schedule to generate pickup windows.</p></div><?php endif; ?></div>
